INSERT INTO products (name, category, technology, description, specs, viscosity, presentations, applications, vehicle_type, image, featured, badge, sort_order) VALUES
('ELAION F10 5W-30', 'elaion', 'Semi-Sintético', 'Lubricante semi-sintético de alta performance para motores nafteros y diesel modernos. La tecnología TEC proporciona máxima protección desde el arranque en frío, reduciendo el desgaste hasta un 40%.', 'API SN/CF • ACEA A3/B4', '5W-30', ARRAY['1L','4L','20L','208L'], ARRAY['Automóviles','SUV','Camionetas'], 'auto', './assets/products/Elaion_FS530.webp', true, 'MÁS VENDIDO', 1),
('ELAION F10 10W-40', 'elaion', 'Semi-Sintético', 'Formulado para motores que requieren mayor viscosidad. Ideal para climas cálidos y motores con mayor kilometraje. Excelente relación costo-beneficio con protección superior.', 'API SN/CF • ACEA A3/B4', '10W-40', ARRAY['1L','4L','20L','208L'], ARRAY['Automóviles','SUV','Camionetas'], 'auto', './assets/products/Elaion_MI1540.webp', false, NULL, 2),
('ELAION F30 5W-40', 'elaion', 'Sintético', 'Lubricante 100% sintético de última generación con tecnología TEC. Máxima protección en todas las condiciones de manejo. Recomendado por las principales marcas automotrices del mundo.', 'API SP • ACEA C3', '5W-40', ARRAY['1L','4L','20L','208L'], ARRAY['Automóviles','SUV','Camionetas','Turbos'], 'auto', './assets/products/Elaion_AURO_FR540.webp', true, 'PREMIUM', 3),
('ELAION F30 5W-30', 'elaion', 'Sintético', 'Aceite 100% sintético de alta tecnología para motores modernos de eficiencia mejorada. Ahorro de combustible comprobado y máxima protección del motor.', 'API SP • ACEA C2/C3', '5W-30', ARRAY['1L','4L','20L'], ARRAY['Automóviles','SUV','Vehículos europeos'], 'auto', './assets/products/Elaion_AURO_FR530.webp', false, NULL, 4),
('ELAION F50 0W-20', 'elaion', 'Sintético Total', 'El aceite más avanzado de la línea ELAION. Diseñado para motores de alta eficiencia que requieren viscosidades ultra-bajas. Máximo ahorro de combustible y protección extrema para vehículos modernos.', 'API SP • ILSAC GF-6A', '0W-20', ARRAY['1L','4L'], ARRAY['Automóviles modernos','Híbridos','Alta eficiencia'], 'auto', './assets/products/Elaion_AURO_FE530.webp', true, 'TECNOLOGÍA TEC', 5),
('ELAION SUV 5W-40', 'elaion', 'Sintético', 'Formulado especialmente para SUVs y 4x4. Soporta las exigencias del manejo off-road y en ciudad. Protege el motor en condiciones extremas de temperatura y carga.', 'API SP • ACEA A3/B4', '5W-40', ARRAY['1L','4L','20L'], ARRAY['SUV','4x4','Camionetas','Off-road'], 'auto', './assets/products/Elaion_AURO_PLUS540.webp', false, 'PARA SUV', 6),
('EXTRAVIDA DX 15W-40', 'extravida', 'Mineral', 'Lubricante mineral multiuso para motores diesel de carga pesada. Formulado con aditivos de alta calidad para maximizar la vida útil del motor. Excelente estabilidad térmica y protección anticorrosiva.', 'API CI-4/SL • ACEA E7', '15W-40', ARRAY['1L','4L','20L','208L'], ARRAY['Camiones','Buses','Maquinaria agrícola','Generadores'], 'camion', './assets/products/extravida_xv_300.webp', true, NULL, 7),
('EXTRAVIDA ULTRA 10W-40', 'extravida', 'Semi-Sintético', 'Lubricante semi-sintético para motores diesel de alta performance. Mayor durabilidad y resistencia a la oxidación. Intervalos de cambio extendidos para mayor eficiencia operativa en flotas.', 'API CI-4 Plus • ACEA E7/E9', '10W-40', ARRAY['20L','208L'], ARRAY['Camiones pesados','Flotas','Maquinaria industrial'], 'camion', './assets/products/extravida_xvt_550_10w_40v.webp', false, 'PLUS', 8),
('EXTRAVIDA MAXIMO 10W-40', 'extravida', 'Sintético', 'La cima de la tecnología EXTRAVIDA. Lubricante 100% sintético para los motores diesel más exigentes de última generación. Máxima protección, mínimo desgaste y mayor intervalo entre cambios.', 'API CK-4 • ACEA E9', '10W-40', ARRAY['20L','208L'], ARRAY['Camiones de última generación','Alta performance diesel','Euro VI'], 'camion', './assets/products/extravida_xvt_650.webp', false, 'MÁXIMO', 9),
('YPF RÖD 4T 10W-40', 'moto', 'Semi-Sintético', 'Lubricante semi-sintético para motores 4 tiempos de motocicletas. La viscosidad 10W-40 lo convierte en el más versátil de la línea RÖD, ideal para uso urbano y de ruta. Certificado JASO MA2 para perfecta compatibilidad con embrague húmedo.', 'API SL • JASO MA2', '10W-40', ARRAY['1L','4L'], ARRAY['Motos 4T','Scooters','Naked','Sport','Uso urbano'], 'moto', './assets/products/rod-4t-10w40.webp', true, 'MÁS RECOMENDADO', 10),
('YPF RÖD 4T 20W-50', 'moto', 'Mineral', 'Lubricante mineral para motocicletas de alta cilindrada o en climas cálidos. La mayor viscosidad 20W-50 brinda protección óptima en condiciones de alta temperatura y uso intensivo. Compatible con embrague húmedo.', 'API SL • JASO MA2', '20W-50', ARRAY['1L','4L'], ARRAY['Motos de alta cilindrada','Climas cálidos','Uso intensivo'], 'moto', './assets/products/rod-4t-20w50.webp', false, NULL, 11),
('YPF RÖD 4T 10W-30', 'moto', 'Semi-Sintético', 'Lubricante semi-sintético de menor viscosidad para motos modernas y scooters de baja cilindrada. Fluye con facilidad en arranques en frío y mantiene excelente protección a temperatura de operación.', 'API SL • JASO MA2', '10W-30', ARRAY['1L','4L'], ARRAY['Scooters','Motos de baja cilindrada','Motos modernas'], 'moto', './assets/products/rod-4t-10w30.webp', false, NULL, 12),
('YPF RÖD 4T 10W-50', 'moto', 'Sintético', 'Lubricante 100% sintético de máxima performance para motocicletas de alto rendimiento. La formulación sintética 10W-50 ofrece protección superior en uso deportivo, altas RPM y temperatura extrema.', 'API SN • JASO MA2', '10W-50', ARRAY['1L','4L'], ARRAY['Motos deportivas','Supersport','Alto rendimiento','Circuito'], 'moto', './assets/products/rod-4t-10w50.webp', false, 'SINTÉTICO', 13),
('YPF RÖD 2T', 'moto', 'Semi-Sintético', 'Lubricante semi-sintético específico para motores 2 tiempos de moto. Formulación de baja emisión de humo y alta lubricidad. Protege el motor y reduce el depósito de carbonilla en válvulas y pistones.', 'API TC • JASO FC', '2T', ARRAY['1L','4L'], ARRAY['Motos 2T','Karts','Motosierras','Equipos de jardín'], 'moto', './assets/products/rod-2t.webp', false, NULL, 14),
('YPF RÖD CADENAS', 'moto', 'Aerosol', 'Lubricante en aerosol para cadenas de motocicletas. Penetra entre los eslabones protegiéndolos de la oxidación y reduciendo el desgaste. Alta adherencia para mantenerse en la cadena incluso en condiciones húmedas.', 'NLGI 00', 'N/A', ARRAY['300ml'], ARRAY['Cadenas de moto','Transmisiones','Cadenas de bicicleta'], 'moto', './assets/products/rod-cadenas.webp', false, NULL, 15),
('KRIOX Refrigerante Rojo', 'otros', 'Pre-diluido', 'Refrigerante pre-diluido listo para usar. Protege el sistema de enfriamiento de la corrosión y el congelamiento. Compatible con todos los metales presentes en el sistema de refrigeración.', 'ASTM D3306 • BS 6580', 'N/A', ARRAY['1L','4L','20L'], ARRAY['Todos los vehículos','Radiadores de aluminio y cobre'], 'auto', './assets/products/refrigerantes_motores_livianos.webp', false, NULL, 16),
('Líquido de Frenos DOT 4', 'otros', 'Fluido hidráulico', 'Líquido de frenos de alta calidad. Punto de ebullición seco de 230°C. Compatible con todos los sistemas de frenos que utilizan DOT 3 y DOT 4. Protección contra la corrosión interna.', 'DOT 4 • SAE J1703 • FMVSS 116', 'N/A', ARRAY['500ml','1L'], ARRAY['Sistemas de frenos hidráulicos','Embragues hidráulicos'], 'auto', './assets/products/liquidos_frenos.webp', false, NULL, 17),
('Grasa EP2 Multipropósito', 'otros', 'Grasa', 'Grasa multipropósito con aditivos de extrema presión (EP). Ideal para rodamientos, articulaciones y bujes de todo tipo de vehículos y maquinaria. Excelente resistencia al agua.', 'NLGI #2 • DIN 51502 KP2K', 'N/A', ARRAY['400g','1kg','18kg'], ARRAY['Rodamientos','Bujes','Articulaciones','Maquinaria'], 'camion', './assets/products/litio.webp', false, NULL, 18),
('Hidráulico AW 68', 'otros', 'Mineral', 'Aceite hidráulico antidesgaste para sistemas hidráulicos industriales y de maquinaria agrícola. Formulado con inhibidores de oxidación, corrosión y antiespumante de alta eficacia.', 'ISO VG 68 • DIN 51524-2 HLP', 'ISO 68', ARRAY['20L','208L'], ARRAY['Maquinaria hidráulica','Tractores','Compresores','Industria'], 'camion', './assets/products/sistemas_hidraulicos.webp', false, NULL, 19);
